changeSet.sql:
UPDATE profile
SET profile.FirstName = account.FirstName,
    profile.LastName = account.LastName,
    profile.Phone = account.Phone
FROM app.MemberProfiles profile
INNER JOIN app.Users account ON account.Id = profile.UserId;

ALTER TABLE app.MemberProfiles DROP CONSTRAINT DF_MemberProfiles_FirstName;
ALTER TABLE app.MemberProfiles DROP CONSTRAINT DF_MemberProfiles_LastName;
DROP INDEX UX_MemberProfiles_TenantId_UserId ON app.MemberProfiles;
ALTER TABLE app.MemberProfiles ALTER COLUMN UserId UNIQUEIDENTIFIER NULL;
CREATE UNIQUE INDEX UX_MemberProfiles_TenantId_UserId
    ON app.MemberProfiles (TenantId, UserId) WHERE UserId IS NOT NULL AND DeletedAt IS NULL;

rollback.sql:
DELETE FROM app.MemberProfiles WHERE UserId IS NULL;
DROP INDEX UX_MemberProfiles_TenantId_UserId ON app.MemberProfiles;
ALTER TABLE app.MemberProfiles ALTER COLUMN UserId UNIQUEIDENTIFIER NOT NULL;
CREATE UNIQUE INDEX UX_MemberProfiles_TenantId_UserId
    ON app.MemberProfiles (TenantId, UserId) WHERE DeletedAt IS NULL;
ALTER TABLE app.MemberProfiles DROP COLUMN FirstName, LastName, Phone;
